/*
 * pio_drivers.c — RP2040 PIO driver implementations for the Open Programmer
 * Pico port.
 *
 * Wraps the autogenerated ow.pio.h / jtag.pio.h / unio.pio.h / uw.pio.h
 * headers and exposes the per-protocol API declared in pio_drivers.h.
 *
 * Resource allocation (see pio_drivers.h header comment):
 *   pio0 SM0 — One-Wire   (ow.pio)
 *   pio0 SM1 — UNI/O      (unio.pio)
 *   pio0 SM2 — JTAG shift (jtag_shift)
 *   pio0 SM3 — JTAG TMS   (jtag_tms)
 *   pio1 SM0 — Microwire  (uw.pio)
 *
 * The pin map matches hal.h:
 *   PIN_SDA = GP10  (OW + UNIO bus, open-drain)
 *   PIN_SCL = GP11  (uWCK)
 *   PIN_SDO = GP27  (uWDI)
 *   PIN_CK  = GP6   (TCK)
 *   PIN_PGM = GP7   (TDI)
 *   PIN_D   = GP5   (TDO)
 *   PIN_A1  = GP15  (TMS, host-driven directly)
 */
#include "pio_drivers.h"
#include "hal.h"
#include "hardware/clocks.h"
#include "hardware/pio.h"
#include "pico/stdlib.h"

// Autogenerated headers (built by pioasm from the .pio files).
#include "ow.pio.h"
#include "jtag.pio.h"
#include "unio.pio.h"
#include "uw.pio.h"

// ---- State ---------------------------------------------------------------
static bool g_init_done = false;

// One-Wire
static PIO  ow_pio  = pio0;
static uint ow_sm   = 0;
static uint ow_off  = 0;

// UNI/O
static PIO  unio_pio = pio0;
static uint unio_sm  = 0;
static uint unio_off = 0;

// JTAG shift
static PIO  jtag_pio  = pio0;
static uint jtag_sm   = 0;
static uint jtag_off  = 0;

// JTAG TMS
static uint jtag_tms_sm  = 0;
static uint jtag_tms_off = 0;

// Microwire
static PIO  uw_pio  = pio1;
static uint uw_sm   = 0;
static uint uw_off  = 0;

// ---- Boot-time init ------------------------------------------------------
void pio_drivers_init(void) {
    if (g_init_done) return;

    uint32_t sys_hz = clock_get_hz(clk_sys);

    // ---- One-Wire on pio0 SM0 (1 MHz = 1 us/cycle) ----
    ow_pio = pio0;
    ow_sm  = pio_claim_unused_sm(ow_pio, true);
    ow_off = pio_add_program(ow_pio, &ow_program);
    ow_program_init(ow_pio, ow_sm, ow_off, PIN_SDA,
                    (float)sys_hz / 1000000.0f);

    // ---- UNI/O on pio0 SM1 (100 kHz = 10 us/cycle = T) ----
    unio_pio = pio0;
    unio_sm  = pio_claim_unused_sm(unio_pio, true);
    unio_off = pio_add_program(unio_pio, &unio_program);
    unio_program_init(unio_pio, unio_sm, unio_off, PIN_SDA,
                      (float)sys_hz / 100000.0f);

    // ---- JTAG shift on pio0 SM2 (clkdiv set for ~1 MHz TCK default) ----
    jtag_pio = pio0;
    jtag_sm  = pio_claim_unused_sm(jtag_pio, true);
    jtag_off = pio_add_program(jtag_pio, &jtag_shift_program);
    // Default TCK = 1 MHz (host can reconfigure via the JTAG_SET_SPEED
    // case if added later). div = sys_hz / (2 * target_tck).
    jtag_shift_program_init(jtag_pio, jtag_sm, jtag_off,
                            TDInum, TDOnum, TCKnum,
                            (float)sys_hz / (2.0f * 1000000.0f));

    // ---- JTAG TMS on pio0 SM3 (same TCK frequency) ----
    jtag_tms_sm  = pio_claim_unused_sm(jtag_pio, true);
    jtag_tms_off = pio_add_program(jtag_pio, &jtag_tms_program);
    jtag_tms_program_init(jtag_pio, jtag_tms_sm, jtag_tms_off, TCKnum,
                          (float)sys_hz / (2.0f * 1000000.0f));

    // ---- Microwire on pio1 SM0 (clkdiv set for ~1 MHz uWCK default) ----
    uw_pio = pio1;
    uw_sm  = pio_claim_unused_sm(uw_pio, true);
    uw_off = pio_add_program(uw_pio, &uw_program);
    uw_program_init(uw_pio, uw_sm, uw_off, PIN_SDO, PIN_SDA, PIN_SCL,
                    (float)sys_hz / (2.0f * 1000000.0f));

    g_init_done = true;
}

// ---- One-Wire API --------------------------------------------------------
bool ow_pio_reset(void) {
    if (!g_init_done) pio_drivers_init();
    pio_sm_put_blocking(ow_pio, ow_sm, ow_CMD_RESET);
    uint32_t v = pio_sm_get_blocking(ow_pio, ow_sm);
    // Reset path does not include recovery; wait for the bus to settle
    // before the next command (spec requires >= 480 us total reset cycle;
    // the SM produced 480 us low + ~62 us presence sample = 542 us).
    busy_wait_us_32(420);
    return (v & 1) == 0;  // presence = bus low at sample time
}

void ow_pio_write_bit(uint bit) {
    if (!g_init_done) pio_drivers_init();
    pio_sm_put_blocking(ow_pio, ow_sm, bit ? ow_CMD_WRITE1 : ow_CMD_WRITE0);
    // The write slot takes ~70 us; wait for completion so back-to-back
    // writes keep the minimum 1-us recovery.
    busy_wait_us_32(70);
}

uint ow_pio_read_bit(void) {
    if (!g_init_done) pio_drivers_init();
    pio_sm_put_blocking(ow_pio, ow_sm, ow_CMD_READ);
    uint32_t v = pio_sm_get_blocking(ow_pio, ow_sm);
    return v & 1;
}

void ow_pio_write_byte(uint8_t byte) {
    for (int i = 0; i < 8; i++) {
        ow_pio_write_bit(byte & 1);
        byte >>= 1;
    }
}

uint8_t ow_pio_read_byte(void) {
    uint8_t byte = 0;
    for (int i = 0; i < 8; i++) {
        byte >>= 1;
        if (ow_pio_read_bit()) byte |= 0x80;
    }
    return byte;
}

// ---- JTAG API ------------------------------------------------------------
void jtag_pio_init(void) {
    if (!g_init_done) pio_drivers_init();
}

uint32_t jtag_pio_shift32(uint32_t tx) {
    if (!g_init_done) pio_drivers_init();
    pio_sm_put_blocking(jtag_pio, jtag_sm, tx);
    return pio_sm_get_blocking(jtag_pio, jtag_sm);
}

void jtag_pio_tms_pulse(uint count) {
    if (!g_init_done) pio_drivers_init();
    if (count == 0) return;
    // Push the count (minus 1, since the loop is "y--" and runs count times).
    pio_sm_put_blocking(jtag_pio, jtag_tms_sm, count - 1);
    // Wait for completion: the SM has no RX push, so we poll the idle state.
    // Simpler: drain by waiting a bounded time. At 1 MHz TCK, count pulses
    // take ~2*count us. We wait that long plus a margin.
    busy_wait_us_32(2 * count + 4);
}

// ---- Microwire API -------------------------------------------------------
uint32_t uw_pio_xfer32(uint32_t tx) {
    if (!g_init_done) pio_drivers_init();
    pio_sm_put_blocking(uw_pio, uw_sm, tx);
    return pio_sm_get_blocking(uw_pio, uw_sm);
}

// ---- UNI/O API -----------------------------------------------------------
void unio_pio_emit_halfbits(uint16_t dir_pattern) {
    if (!g_init_done) pio_drivers_init();
    // The SM shifts 16 bits MSB-first from the OSR into pindirs. We push
    // the pattern left-justified? No — out_shift is right, so bit 0 of the
    // OSR is shifted first. We need MSB (bit 15) first, so we bit-reverse
    // the pattern before pushing.
    uint16_t rev = 0;
    for (int i = 0; i < 16; i++) {
        rev = (rev << 1) | (dir_pattern & 1);
        dir_pattern >>= 1;
    }
    pio_sm_put_blocking(unio_pio, unio_sm, (uint32_t)rev);
    // Drain the completion word so the FIFO doesn't fill up.
    (void)pio_sm_get_blocking(unio_pio, unio_sm);
}
